function validDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;return key(dateObj(s))===s&&s>='1900-01-01'&&s<='2200-12-31';}
function validate(raw){
 const fail=message=>{throw Error(message);};const str=(v,n=500)=>typeof v==='string'&&v.length<=n;const ident=v=>str(v,100)&&!['__proto__','constructor','prototype'].includes(v)&&/^[a-zA-Z0-9_-]+$/.test(v);const days=v=>Array.isArray(v)&&v.length>0&&v.length<=7&&new Set(v).size===v.length&&v.every(x=>Number.isInteger(x)&&x>=0&&x<=6);
 if(!raw||![1,2,3,4,5,6,7,8].includes(raw.schemaVersion))fail('La copia no corresponde a esta versión de Rumbo.');
 if(!Array.isArray(raw.events)||raw.events.length>10000||!Array.isArray(raw.habits)||raw.habits.length>200||!Array.isArray(raw.routes)||raw.routes.length>30)fail('La estructura de la copia no es válida.');
 const ids=new Set();for(const e of raw.events){if(!ident(e.id)||ids.has(e.id)||!str(e.title,120)||!e.title.trim()||!CAT[e.category]||!['once','weekly'].includes(e.repeat)||!validDate(e.startDate)||(e.endDate&&!validDate(e.endDate))||!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.end)||minutes(e.start)<0||minutes(e.end)>1439||minutes(e.end)<=minutes(e.start)||!days(e.days)||!str(e.notes??'',1000))fail('Hay un bloque de horario no válido.');ids.add(e.id);}
 const hids=new Set();for(const h of raw.habits){if(!ident(h.id)||hids.has(h.id)||!str(h.name,90)||!h.name.trim()||!str(h.emoji,16)||!str(h.note??'',300)||!Array.isArray(h.rules)||h.rules.length>10000||!h.rules.length)fail('Hay un hábito no válido.');for(const rule of h.rules)if(!validDate(rule.from)||!days(rule.days)||typeof rule.active!=='boolean')fail('El historial de un hábito no es válido.');hids.add(h.id);}
 const records=(obj,name)=>{if(!obj||typeof obj!=='object'||Array.isArray(obj)||Object.keys(obj).length>15000)fail(`Los registros de ${name} no son válidos.`);for(const [d,values]of Object.entries(obj)){if(!validDate(d)||!values||typeof values!=='object'||Array.isArray(values)||Object.keys(values).length>12000)fail(`Hay una fecha no válida en ${name}.`);for(const [k,v]of Object.entries(values))if(!ident(k)||typeof v!=='boolean')fail(`Hay una marca no válida en ${name}.`);}};
 records(raw.habitLogs,'hábitos');records(raw.eventLogs,'horario');
 if(!raw.overrides||typeof raw.overrides!=='object'||Array.isArray(raw.overrides)||Object.keys(raw.overrides).length>30000)fail('Las excepciones del horario no son válidas.');
 for(const [k,v]of Object.entries(raw.overrides)){const split=k.lastIndexOf('|');if(!ident(k.slice(0,split))||!validDate(k.slice(split+1))||!v||typeof v!=='object')fail('Una excepción no es válida.');if(!v.cancelled&&(!str(v.title,120)||!CAT[v.category]||!/^([01]\d|2[0-3]):[0-5]\d$/.test(v.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(v.end)||minutes(v.end)<=minutes(v.start)||minutes(v.end)>1439||!str(v.notes??'',1000)))fail('Un bloque modificado no es válido.');}
 if(!raw.notes||typeof raw.notes!=='object'||Array.isArray(raw.notes)||Object.keys(raw.notes).length>15000)fail('Las notas no son válidas.');for(const [d,n]of Object.entries(raw.notes))if(!validDate(d)||!str(n,2000))fail('Una nota no es válida.');
 for(const r of raw.routes){if(!ident(r.id)||!str(r.name,120)||!str(r.emoji,16)||!str(r.goal,1500)||!Array.isArray(r.steps)||r.steps.length>200)fail('Una ruta no es válida.');const seen=new Set();for(const s of r.steps){if(!ident(s.id)||seen.has(s.id)||!str(s.title,120)||!str(s.period,100)||!str(s.topics,2000)||!str(s.goal,2000)||typeof s.done!=='boolean')fail('Una meta no es válida.');seen.add(s.id);}}
 if(raw.profile&&!str(raw.profile.name,60))fail('El nombre no es válido.');
 const extensions=validateExtensions(raw);
 return clone({schemaVersion:SCHEMA,...extensions,assistant:validateAssistant(raw.assistant),createdAt:raw.createdAt||new Date().toISOString(),updatedAt:raw.updatedAt||null,lastExportAt:raw.lastExportAt||null,profile:{name:raw.profile?.name||''},events:raw.events,overrides:raw.overrides,habits:raw.habits,habitLogs:raw.habitLogs,eventLogs:raw.eventLogs,notes:raw.notes,routes:attachAssessmentKeys(raw.routes)});
}

function request(req){return new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error);});}
async function initStorage(){try{db=await new Promise((res,rej)=>{const r=indexedDB.open('RumboPlanner',1);const timer=setTimeout(()=>rej(Error('El almacenamiento tardó demasiado.')),3500);r.onupgradeneeded=()=>{r.result.createObjectStore('data');r.result.createObjectStore('backups');};r.onsuccess=()=>{clearTimeout(timer);res(r.result);};r.onerror=()=>{clearTimeout(timer);rej(r.error);};r.onblocked=()=>{clearTimeout(timer);rej(Error('Cierra otras pestañas de Rumbo y vuelve a abrir.'));};});storageMode='indexeddb';const stored=await request(db.transaction('data').objectStore('data').get('current'));if(stored){try{state=validate(stored);}catch(err){recoveryData=stored;state=seed();storageMode='memory';storageError='Los datos anteriores no se pudieron leer. No se han borrado. Exporta una copia de recuperación antes de restaurar otra copia.';return;}}else state=seed();diskState=clone(stored||state);if(!stored||stored.schemaVersion!==SCHEMA)await save();}
 catch(err){let stored=null;try{stored=localStorage.getItem('rumbo-v1');const raw=stored?JSON.parse(stored):null;if(raw){try{state=validate(raw);}catch(e){recoveryData=raw;state=seed();storageMode='memory';storageError='Los datos locales anteriores no se pudieron leer. No se han borrado. Exporta una copia de recuperación antes de restaurar otra copia.';return;}}else state=seed();diskState=clone(raw||state);storageMode='local';await save();}catch(e){state=seed();diskState=clone(state);storageMode='memory';if(stored){recoveryData={format:'rumbo-recovery-text',originalText:stored};storageError='La copia local no se pudo interpretar. Exporta la recuperación para conservar su contenido original.';}else storageError='Este navegador no permite guardar los datos. Exporta una copia antes de cerrar o abre Rumbo en otro navegador.';}}
}
async function save(){const snapshot=clone(state);snapshot.writeId=id();pendingSaves++;saving=true;updateSaveStatus();saveQueue=saveQueue.catch(()=>{}).then(async()=>{if(storageMode==='memory')throw Error(storageError||'No se pudo guardar en este navegador.');if(storageMode==='local'){const current=JSON.parse(localStorage.getItem('rumbo-v1')||'null');if(current&&(current.writeId||null)!==(diskState?.writeId||null))throw Error('Hay cambios guardados en otra pestaña. Recarga Rumbo antes de continuar.');localStorage.setItem('rumbo-v1',JSON.stringify(snapshot));diskState=snapshot;state.writeId=snapshot.writeId;return;}
 await new Promise((res,rej)=>{const tx=db.transaction(['data','backups'],'readwrite');let conflict=false;const b=tx.objectStore('backups'),get=b.get(today());get.onsuccess=()=>{if(!get.result&&diskState)b.put(clone(diskState),today());const keys=b.getAllKeys();keys.onsuccess=()=>{for(const k of keys.result.sort().slice(0,-7))b.delete(k);};};const current=tx.objectStore('data').get('current');current.onsuccess=()=>{if(current.result&&(current.result.writeId||null)!==(diskState?.writeId||null)){conflict=true;tx.abort();return;}tx.objectStore('data').put(snapshot,'current');};tx.oncomplete=()=>{diskState=snapshot;state.writeId=snapshot.writeId;res();};tx.onerror=()=>rej(conflict?Error('Hay cambios guardados en otra pestaña. Recarga Rumbo antes de continuar.'):tx.error);tx.onabort=()=>rej(conflict?Error('Hay cambios guardados en otra pestaña. Recarga Rumbo antes de continuar.'):tx.error||Error('Guardado interrumpido.'));});
 });try{await saveQueue;pendingSaves--;saving=pendingSaves>0;storageError='';updateSaveStatus();return true;}catch(err){pendingSaves--;saving=pendingSaves>0;storageError=err?.message?.includes('otra pestaña')?err.message:'No se pudo guardar el último cambio. Exporta tus datos ahora para conservarlos.';updateSaveStatus();toast(storageError);return false;}}
function persist(){invalidateLedger();syncGoals();state.updatedAt=new Date().toISOString();render();return save();}
function updateSaveStatus(){document.querySelectorAll('[data-save-status]').forEach(e=>e.textContent=storageError?'Pendiente de guardar':saving?'Guardando…':'Guardado en este navegador');if(typeof assistantUpdateStatus==='function')assistantUpdateStatus();}
function toast(message,undo,actionLabel='Deshacer'){const box=document.createElement('div');box.className='toast';const span=document.createElement('span');span.textContent=message;box.append(span);if(undo){const b=document.createElement('button');b.textContent=actionLabel;b.onclick=()=>{undo();box.remove();};box.append(b);}document.querySelector('#toasts').append(box);setTimeout(()=>box.remove(),undo?8000:4500);}

function habitRule(h,d){let result=null;for(const r of [...h.rules].sort((a,b)=>a.from.localeCompare(b.from)))if(r.from<=d)result=r;return result;}
function dueHabit(h,d){const r=habitRule(h,d);return !!r&&r.active&&r.days.includes(dayIndex(d));}
function habitsFor(d){return state.habits.filter(h=>dueHabit(h,d));}
function eventsFor(d){return state.events.flatMap(e=>{const override=state.overrides[`${e.id}|${d}`];if(override?.cancelled)return [];const due=e.repeat==='once'?d===e.startDate:d>=e.startDate&&(!e.endDate||d<=e.endDate)&&e.days.includes(dayIndex(d));if(!due)return [];return [{...e,...override,date:d,completed:!!state.eventLogs[d]?.[e.id]}];}).sort((a,b)=>a.start.localeCompare(b.start));}
function habitDay(d){if(d>today())return {done:0,total:0,future:true};const hs=habitsFor(d);return {done:hs.filter(h=>state.habitLogs[d]?.[h.id]).length,total:hs.length,future:false};}
function periodBounds(){const a=ui.periodAnchor;if(ui.periodMode==='week'){const from=monday(a);return {from,to:add(from,6)};}const d=dateObj(a);return {from:key(new Date(d.getFullYear(),d.getMonth(),1,12)),to:key(new Date(d.getFullYear(),d.getMonth()+1,0,12))};}
function periodStats(from,to){let done=0,total=0,plannedMinutes=0,doneMinutes=0,eventDone=0;const series=range(from,to).map(d=>{const h=habitDay(d);if(!h.future){done+=h.done;total+=h.total;for(const e of eventsFor(d)){plannedMinutes+=duration(e);if(e.completed){doneMinutes+=duration(e);eventDone++;}}}return {date:d,...h};});return {done,total,plannedMinutes,doneMinutes,eventDone,series};}
function streak(){const earliest=state.habits.flatMap(h=>h.rules.map(r=>r.from)).sort()[0]||today();let d=today(),count=0;let h=habitDay(d);if(h.total&&h.done!==h.total)d=add(d,-1);for(let i=0;i<10000&&d>=earliest&&d>=`${FIRST}-01-01`;i++,d=add(d,-1)){h=habitDay(d);if(!h.total)continue;if(h.done!==h.total)break;count++;}return count;}
function setRule(h,rule){h.rules=h.rules.filter(r=>r.from!==rule.from);h.rules.push(rule);h.rules.sort((a,b)=>a.from.localeCompare(b.from));}
function habitToggle(hid,d){const h=state.habits.find(h=>h.id===hid);if(!h)return;if(d>today()){toast('Esa fecha todavía no llega. Puedes marcar los hábitos de hoy.',()=>{ui.date=today();render();},'Ir a hoy');return;}if(!dueHabit(h,d)){toast('Este hábito no estaba previsto en esa fecha. Revisa sus días o elige Hoy.');return;}const old=!!state.habitLogs[d]?.[hid];if(!state.habitLogs[d])state.habitLogs[d]={};state.habitLogs[d][hid]=!old;persist();toast(!old?'Un pequeño paso más. Hábito marcado.':'Marca retirada.',()=>{state.habitLogs[d][hid]=old;persist();});}
function eventToggle(eid,d){if(d>today())return;state.eventLogs[d]??={};state.eventLogs[d][eid]=!state.eventLogs[d][eid];persist();}

function render(){if(!state)return;const navs=[['today','home','Hoy'],['assistant','spark','Mi asistente'],['schedule','calendar','Mi horario'],['habits','habits','Mis hábitos'],['goals','target','Metas'],['business','shop','Ventas'],['progress','chart','Mi progreso'],['routes','route','Mi ruta']];const heading={assistant:'Tu ayuda personal',today:'Tu espacio personal',schedule:'Tiempo para lo importante',habits:'Pequeñas acciones, cada día',goals:'Lo que quieres construir',business:'Tu negocio, en orden',progress:'Mira lo que vas construyendo',routes:'Aprender con dirección',settings:'Tus datos, siempre contigo'};
 document.querySelector('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('sun',28)}</span>rumbo<span style="color:#c3d4a5">.</span></div><p class="tagline">UN DÍA A LA VEZ</p><div class="nav-label">Mi espacio</div><nav aria-label="Principal">${navs.map(([v,i,n])=>`<button class="nav-item ${ui.view===v?'active':''}" data-action="view" data-view="${v}" ${ui.view===v?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-card"><div class="plant">🌱</div><strong>No necesitas hacerlo todo hoy.</strong><p>Haz espacio para lo que te acerca a quien quieres ser.</p></div><button class="nav-item ${ui.view==='settings'?'active':''}" data-action="view" data-view="settings">${icon('settings')}Ajustes y copias</button><div class="nav-foot">2026 — 2051 · A tu ritmo</div></div></aside><main class="main"><header class="topbar"><div class="topbar-title">${heading[ui.view]}<small>${cap(fmtDate(today(),true))}</small></div><div class="mobile-brand">${icon('sun',25)}rumbo.</div><div class="topbar-actions"><span class="backup-indicator">${icon('shield',14)}<span data-save-status></span></span>${topAction()}<button class="assistant-header-btn" data-action="assistant-open" aria-label="Abrir mi asistente">${icon('spark',17)}<span class="assistant-header-label">Asistente</span></button><button class="avatar" data-action="view" data-view="settings" aria-label="Abrir ajustes">${esc((state.profile.name||'T')[0].toUpperCase())}</button></div></header><div class="content">${storageError?`<div class="storage-alert"><strong>Tu último cambio necesita una copia.</strong>${esc(storageError)} <button class="text-btn" data-action="export">Exportar ahora</button></div>`:''}${({assistant:renderAssistant,today:renderToday,schedule:renderSchedule,habits:renderHabits,goals:renderGoals,business:renderBusiness,progress:renderProgress,routes:renderRoutes,settings:renderSettings}[ui.view]||renderToday)()}</div></main>${renderMobileNav()}</div>`;updateSaveStatus();keepBusinessTabVisible();if(ui.view==='assistant')assistantAfterRender();}
function dateControls(d=ui.date){return `<div class="date-control"><button class="icon-btn" data-action="date-step" data-delta="-1" aria-label="Día anterior" ${d<=`${FIRST}-01-01`?'disabled':''}>${icon('left',16)}</button><span class="date-label">${d===today()?'Hoy, ':''}${fmtDate(d)}</span><button class="icon-btn" data-action="date-step" data-delta="1" aria-label="Día siguiente" ${d>=`${LAST}-12-31`?'disabled':''}>${icon('right',16)}</button><label class="date-input"><input type="date" id="selected-date" aria-label="Elegir fecha" value="${d}" min="${FIRST}-01-01" max="${LAST}-12-31"></label>${d!==today()?'<button class="btn soft small" data-action="habit-go-today">Hoy</button>':''}</div>`;}
function heading(title,sub,right=''){return `<div class="page-heading"><div><div class="eyebrow">Mi espacio · Rumbo</div><h1>${title}</h1><p>${sub}</p></div>${right}</div>`;}
function checkButton(action,eid,d,checked,disabled,label){return `<button class="check ${checked?'checked':''}" data-action="${action}" data-id="${eid}" data-date="${d}" aria-label="${esc(label)}" aria-pressed="${checked}" ${disabled?'disabled':''}>${checked?icon('check',17):''}</button>`;}
function agenda(d){const es=eventsFor(d);return es.length?es.map(e=>`<div class="agenda-item ${e.completed?'done':''}"><div class="time">${e.start}</div><button class="agenda-card" style="--cat:${CAT[e.category].color}" data-action="event-edit" data-id="${e.id}" data-date="${d}"><strong>${esc(e.title)}</strong><small>${e.start} — ${e.end} · ${timeText(duration(e))}${e.repeat==='weekly'?' · Semanal':''}</small></button>${checkButton('event-toggle',e.id,d,e.completed,d>today(),`${e.completed?'Desmarcar':'Completar'} ${e.title}`)}</div>`).join(''):`<div class="empty"><div class="empty-icon">${icon('sun',26)}</div><strong>Un poco de espacio libre</strong>Añade un bloque o deja tiempo para descansar.<br><button class="btn soft small" data-action="event-new" data-date="${d}">${icon('plus',14)}Añadir un bloque</button></div>`;}
function habitRows(d){const hs=habitsFor(d);return hs.length?hs.map(h=>{const done=!!state.habitLogs[d]?.[h.id];return `<div class="habit-row ${done?'done':''}"><div class="habit-icon">${esc(h.emoji)}</div><div class="habit-main"><strong>${esc(h.name)}</strong><small>${esc(h.note||'Un paso a la vez')}</small></div>${checkButton('habit-toggle',h.id,d,done,d>today(),`${done?'Desmarcar':'Cumplí'} ${h.name}`)}</div>`;}).join(''):`<div class="empty"><div class="empty-icon">${icon('leaf',26)}</div><strong>Sin hábitos para esta fecha</strong>Los hábitos cuentan a partir de su fecha de inicio.<br><button class="btn soft small" data-action="habit-new">Crear un hábito</button></div>`;}
function ring(done,total){const percent=pct(done,total),r=17,c=2*Math.PI*r;return `<svg class="ring" viewBox="0 0 44 44" role="img" aria-label="${percent}% completado"><circle cx="22" cy="22" r="${r}" fill="none" stroke="#dce7d6" stroke-width="4"/><circle cx="22" cy="22" r="${r}" fill="none" stroke="#39775c" stroke-width="4" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-percent/100)}" transform="rotate(-90 22 22)" stroke-linecap="round"/><text x="22" y="25" text-anchor="middle" font-size="10" font-weight="700" fill="#39775c">${percent}%</text></svg>`;}
function renderToday(){const d=ui.date,h=d>today()?{done:0,total:habitsFor(d).length}:habitDay(d),es=eventsFor(d),week=periodStats(monday(d),add(monday(d),6)),greeting=state.profile.name?`Hola, ${esc(state.profile.name)}.`:'Tu próximo paso empieza hoy.';return `${heading('Un día a la vez.','Organiza tu tiempo. Cuida tus hábitos. Celebra lo que sí hiciste.',dateControls())}<section class="hero"><div><div class="eyebrow">${greeting}</div><h2>Pequeños pasos,<br>grandes cambios.</h2><p>Tu horario es una guía, no una carrera. Puedes cambiarlo para que se parezca a tu vida.</p></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="stem"></div><div class="leaf"></div><div class="leaf b"></div><div class="leaf c"></div><div class="pot"></div><div class="spark">✦</div><div class="hero-progress"><span class="mini-check">✓</span>Hoy también cuenta.</div></div></section><div class="stats"><div class="stat"><div class="stat-top">${icon('habits',16)}Hábitos del día</div><strong>${h.done}<em> / ${h.total}</em></strong><small>${d>today()?'Las marcas se habilitan ese día':'Cada marca es un paso real'}</small></div><div class="stat"><div class="stat-top">${icon('calendar',16)}Bloques de hoy</div><strong>${es.filter(e=>e.completed).length}<em> / ${es.length}</em></strong><small>Tu horario, a tu ritmo</small></div><div class="stat"><div class="stat-top">${icon('clock',16)}Tiempo planificado</div><strong>${timeText(es.reduce((n,e)=>n+duration(e),0))}</strong><small>Para la fecha seleccionada</small></div><div class="stat"><div class="stat-top">${icon('leaf',16)}Días completos seguidos</div><strong>${streak()}<em> días</em></strong><small>Hábitos previstos cumplidos</small></div></div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Tu agenda</h2><p>${cap(fmtDate(d,true))}</p></div><button class="text-btn" data-action="view" data-view="schedule">Ver horario ${icon('right',14)}</button></div><div class="panel-body">${agenda(d)}</div></section><section class="panel"><div class="panel-head"><div><h2>Lo bueno de cada día</h2><p>No tiene que ser perfecto para contar.</p></div><button class="icon-btn" data-action="habit-new" aria-label="Añadir hábito">${icon('plus',16)}</button></div><div class="panel-body"><div class="habit-summary">${ring(h.done,h.total)}<div><strong>${h.done===h.total&&h.total?'Un día completo. Bien hecho.':`${h.done} de ${h.total} hábitos cumplidos`}</strong><small>${h.total?'Marca solo lo que hayas hecho.':'Puedes comenzar cuando quieras.'}</small></div></div>${habitRows(d)}</div></section></div><div class="grid-2 section-gap"><section class="panel"><div class="panel-head"><div><h2>Así va tu semana</h2><p>${week.done} de ${week.total} marcas previstas hasta hoy</p></div><button class="text-btn" data-action="view" data-view="progress">Ver progreso ${icon('right',14)}</button></div><div class="panel-body">${barChart(week.series,'habits',true)}</div></section><section class="panel"><div class="panel-head"><div><h2>Una línea para tu día</h2><p>¿Qué aprendiste o qué te gustaría ajustar?</p></div>${icon('edit',16)}</div><div class="panel-body"><form id="note-form"><textarea class="note-input" name="note" maxlength="2000" placeholder="Hoy me di cuenta de que…" aria-label="Nota del día">${esc(state.notes[d]||'')}</textarea><div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="btn soft small" type="submit">Guardar nota</button></div></form></div></section></div>`;}

function renderSchedule(){const d=dateObj(ui.date),from=monday(ui.date),week=range(from,add(from,6));return `${heading('Hazle espacio a tus planes.','Edita cualquier bloque. Repite lo que te sirve y cambia lo que necesites.')}
 <div class="banner">${icon('spark',18)}Incluí una plantilla de Python, robótica e inglés. Los horarios son una propuesta: ajústalos a tus clases y a tu descanso.</div><div class="toolbar"><div class="segmented"><button data-action="schedule-mode" data-mode="week" class="${ui.scheduleMode==='week'?'active':''}">Semana</button><button data-action="schedule-mode" data-mode="month" class="${ui.scheduleMode==='month'?'active':''}">Mes</button></div><div class="date-control"><button class="icon-btn" data-action="calendar-step" data-delta="-1" aria-label="Periodo anterior">${icon('left',16)}</button><span class="date-label">${ui.scheduleMode==='week'?`${fmtDate(from)} — ${fmtDate(add(from,6))}`:`${cap(MONTH[d.getMonth()])} ${d.getFullYear()}`}</span><button class="icon-btn" data-action="calendar-step" data-delta="1" aria-label="Periodo siguiente">${icon('right',16)}</button><button class="btn secondary small" data-action="go-today">Hoy</button></div><div class="calendar-jump"><select id="jump-month" aria-label="Mes">${MONTH.map((m,i)=>`<option value="${i}" ${i===d.getMonth()?'selected':''}>${cap(m)}</option>`).join('')}</select><select id="jump-year" aria-label="Año">${Array.from({length:LAST-FIRST+1},(_,i)=>`<option ${FIRST+i===d.getFullYear()?'selected':''}>${FIRST+i}</option>`).join('')}</select></div></div><div class="panel calendar-shell">${ui.scheduleMode==='week'?`<div class="week-grid">${week.map(date=>`<section class="week-day"><button class="day-head ${date===today()?'today':''} ${date===ui.date?'selected':''}" data-action="pick-date" data-date="${date}" style="width:100%"><small>${DAY[dayIndex(date)]}</small><span class="day-num">${dateObj(date).getDate()}</span></button><div class="week-day-body">${eventsFor(date).map(e=>`<button class="calendar-event ${e.completed?'done':''}" style="--cat:${CAT[e.category].color}" data-action="event-edit" data-id="${e.id}" data-date="${date}"><strong>${esc(e.title)}</strong><small>${e.start} — ${e.end}${e.completed?' · ✓':''}</small></button>`).join('')}<button class="day-add" data-action="event-new" data-date="${date}" ${!inRange(date)?'disabled':''}>${icon('plus',12)}Añadir</button></div></section>`).join('')}</div>`:monthCalendar(ui.date)}</div><div class="legend" style="margin-top:14px">${Object.values(CAT).map(c=>`<span><i class="dot" style="background:${c.color}"></i>${c.name}</span>`).join('')}</div><div class="calendar-below"><section class="panel"><div class="panel-head"><div><h2>${cap(fmtDate(ui.date,true))}</h2><p>Pulsa un bloque para editarlo.</p></div><button class="icon-btn" data-action="event-new" aria-label="Añadir bloque">${icon('plus',16)}</button></div><div class="panel-body">${agenda(ui.date)}</div></section><section class="panel"><div class="panel-head"><div><h2>Hábitos para esta fecha</h2><p>${ui.date>today()?'Puedes verlos ahora y marcarlos cuando llegue el día.':'También puedes corregir marcas de días anteriores.'}</p></div></div><div class="panel-body">${habitRows(ui.date)}</div></section></div><p class="muted-note">${icon('calendar',14)}Calendario disponible de enero de ${FIRST} a diciembre de ${LAST}: 26 años para organizarte.</p>`;}
function monthCalendar(anchor){const d=dateObj(anchor),first=key(new Date(d.getFullYear(),d.getMonth(),1,12)),start=monday(first);return `<div class="month-grid">${DAY.map(n=>`<div class="month-weekday">${n}</div>`).join('')}${range(start,add(start,41)).map(date=>{const es=eventsFor(date);return `<div class="month-cell ${dateObj(date).getMonth()!==d.getMonth()?'outside':''} ${date===today()?'today':''} ${date===ui.date?'selected':''}" data-action="pick-date" data-date="${date}" role="button" tabindex="0" aria-label="${esc(fmtDate(date,true))}; ${es.length} bloques"><span class="n">${dateObj(date).getDate()}</span>${es.slice(0,2).map(e=>`<div class="month-event" style="--cat:${CAT[e.category].color}">${e.start} ${esc(e.title)}</div>`).join('')}${es.length>2?`<small class="more">+${es.length-2} más</small>`:''}</div>`;}).join('')}</div>`;}

function renderHabits(){const active=state.habits.filter(h=>!h.archived),archived=state.habits.filter(h=>h.archived);return `${heading('Lo que repites te construye.','Crea hábitos sencillos, elige sus días y registra tus avances.',`<button class="btn" data-action="habit-new">${icon('plus',16)}Nuevo hábito</button>`)}${dateControls()}${habitDateNotice()}<div class="habit-cards section-gap">${active.map(h=>{const bounds={from:monday(ui.date),to:add(monday(ui.date),6)},days=range(bounds.from,bounds.to);let done=0,total=0;days.forEach(d=>{if(d<=today()&&dueHabit(h,d)){total++;if(state.habitLogs[d]?.[h.id])done++;}});const rule=habitRule(h,ui.date),due=dueHabit(h,ui.date),checked=!!state.habitLogs[ui.date]?.[h.id];return `<article class="habit-card"><div class="habit-card-head"><div class="habit-icon">${esc(h.emoji)}</div><button class="icon-btn" data-action="habit-edit" data-id="${h.id}" aria-label="Editar ${esc(h.name)}">${icon('edit',15)}</button></div><h3>${esc(h.name)}</h3><p>${esc(h.note||'A tu ritmo, un día a la vez.')}</p><div class="progress-track"><span style="width:${pct(done,total)}%"></span></div><div class="week-marks">${days.map(d=>{const eligible=dueHabit(h,d),marked=!!state.habitLogs[d]?.[h.id];return `<button data-action="habit-toggle" data-id="${h.id}" data-date="${d}" class="${eligible&&marked?'on':''} ${!eligible?'offday':''}" ${d>today()||!eligible?'disabled':''} aria-label="${esc(h.name)}, ${fmtDate(d)}: ${marked?'cumplido':eligible?'sin marcar':'no programado'}" aria-pressed="${eligible&&marked}" title="${fmtDate(d)}"><span>${eligible&&marked?'✓':DAY[dayIndex(d)][0]}</span><small>${dateObj(d).getDate()}</small></button>`;}).join('')}</div><div class="habit-card-foot"><span>${done} de ${total} esta semana</span>${habitCompleteButton(h,due,checked)}</div></article>`;}).join('')||`<div class="panel empty"><strong>Tu primer hábito puede ser pequeño.</strong>Elige algo que puedas repetir con calma.</div>`}</div><p class="muted-note">${icon('shield',14)}Los cambios de frecuencia se aplican desde hoy y conservan el historial anterior. Las fechas futuras no cuentan en tus porcentajes.</p>${archived.length?`<section class="panel section-gap"><div class="panel-head"><h2>Hábitos archivados</h2><span class="count-pill">${archived.length}</span></div><div class="panel-body">${archived.map(h=>`<div class="archived-item"><span>${esc(h.emoji)} ${esc(h.name)}</span><button class="btn soft small" data-action="habit-restore" data-id="${h.id}">Retomar</button></div>`).join('')}</div></section>`:''}`;}

function barChart(series,metric='habits',small=false){const w=700,h=small?180:255,l=62,r=14,b=33,top=28,area=w-l-r;let vals=series.map(s=>metric==='habits'?(s.total?s.done/s.total*100:null):(s.date>today()?null:eventsFor(s.date).filter(e=>e.completed).reduce((n,e)=>n+duration(e),0)));const max=metric==='habits'?100:Math.max(60,Math.ceil(Math.max(0,...vals.map(v=>v??0))/60)*60),available=h-b-top,step=area/Math.max(1,series.length),bw=Math.min(50,step*.57);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${metric==='habits'?'Porcentaje diario de hábitos cumplidos':'Minutos diarios de bloques completados'}">${[0,.5,1].map(n=>`<line x1="${l}" y1="${top+available*(1-n)}" x2="${w-r}" y2="${top+available*(1-n)}" stroke="#eaf0e5"/><text x="${l-8}" y="${top+available*(1-n)+4}" text-anchor="end">${Math.round(max*n)}${metric==='habits'?'%':''}</text>`).join('')}${series.map((s,i)=>{const v=vals[i],bar=v===null?0:available*v/max,x=l+step*i+(step-bw)/2,y=top+available-bar;const label=series.length<=7?DAY[dayIndex(s.date)]:String(dateObj(s.date).getDate());return `<g><title>${fmtDate(s.date)}: ${v===null?'sin datos previstos':Math.round(v)+(metric==='habits'?'%':' minutos')}</title>${v===null?`<line x1="${x+bw/2-3}" y1="${h-b-4}" x2="${x+bw/2+3}" y2="${h-b-4}" stroke="#c6cfc0" stroke-width="2"/>`:`<rect class="chart-bar" x="${x}" y="${y}" width="${bw}" height="${Math.max(v===0?2:0,bar)}" rx="${Math.min(6,bw/2)}"/>`}${series.length<=7&&v!==null?`<text class="chart-value" x="${x+bw/2}" y="${y-8}" text-anchor="middle">${Math.round(v)}${metric==='habits'?'%':''}</text>`:''}${series.length<=7||i===0||(dateObj(s.date).getDate()%5===0)?`<text x="${x+bw/2}" y="${h-8}" text-anchor="middle">${label}</text>`:''}</g>`;}).join('')}</svg>`;}
function renderProgress(){const {from,to}=periodBounds(),s=periodStats(from,to),label=ui.periodMode==='week'?`${fmtDate(from)} — ${fmtDate(to)}`:`${cap(MONTH[dateObj(from).getMonth()])} ${dateObj(from).getFullYear()}`;return `${heading('Tu esfuerzo, en perspectiva.','Un registro honesto de lo que haces, semana a semana.')}<div class="toolbar"><div class="segmented"><button data-action="period-mode" data-mode="week" class="${ui.periodMode==='week'?'active':''}">Semana</button><button data-action="period-mode" data-mode="month" class="${ui.periodMode==='month'?'active':''}">Mes</button></div><div class="date-control"><button class="icon-btn" data-action="period-step" data-delta="-1" aria-label="Periodo anterior">${icon('left',16)}</button><span class="date-label">${label}</span><button class="icon-btn" data-action="period-step" data-delta="1" aria-label="Periodo siguiente">${icon('right',16)}</button><button class="btn secondary small" data-action="period-today">Actual</button></div></div><div class="analytics-top"><div class="stat"><div class="stat-top">Hábitos cumplidos</div><strong>${s.total?pct(s.done,s.total)+'%':'—'}</strong><small>${s.done} de ${s.total} marcas previstas</small></div><div class="stat"><div class="stat-top">Bloques completados</div><strong>${s.eventDone}</strong><small>Registrados en tu horario</small></div><div class="stat"><div class="stat-top">Tiempo cumplido</div><strong>${timeText(s.doneMinutes)}</strong><small>De ${timeText(s.plannedMinutes)} planificados</small></div></div><section class="panel chart-panel"><div class="chart-header"><div><h2>${ui.metric==='habits'?'Constancia diaria':'Tiempo completado por día'}</h2><p class="subtle" style="font-size:11px;margin-top:5px">${ui.metric==='habits'?'Cada día según los hábitos que tenías previstos.':'Minutos de los bloques que marcaste como completos.'}</p></div><div class="segmented"><button data-action="metric" data-metric="habits" class="${ui.metric==='habits'?'active':''}">Hábitos</button><button data-action="metric" data-metric="schedule" class="${ui.metric==='schedule'?'active':''}">Horario</button></div></div>${barChart(s.series,ui.metric)}<p class="muted-note">${icon('shield',13)}Solo cuentan las fechas hasta hoy. Un guion indica que no había hábitos previstos.</p></section><div class="grid-2 section-gap"><section class="panel"><div class="panel-head"><div><h2>Un hábito a la vez</h2><p>Cumplimiento durante el periodo seleccionado</p></div></div><div class="panel-body">${state.habits.map(h=>{const days=range(from,minDate(to,today())).filter(d=>dueHabit(h,d)),n=days.filter(d=>state.habitLogs[d]?.[h.id]).length;return days.length?`<div class="progress-row"><div>${esc(h.emoji)} ${esc(h.name)}</div><div class="progress-track"><span style="width:${pct(n,days.length)}%"></span></div><span>${n}/${days.length}</span></div>`:'';}).join('')||'<div class="empty">Todavía no hay hábitos previstos en este periodo.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Tu mapa del mes</h2><p>${cap(MONTH[dateObj(ui.periodAnchor).getMonth()])} · cada tono cuenta una pequeña historia</p></div></div><div class="panel-body">${heatmap(ui.periodAnchor)}</div></section></div>`;}
function heatmap(anchor){const d=dateObj(anchor),from=key(new Date(d.getFullYear(),d.getMonth(),1,12)),to=key(new Date(d.getFullYear(),d.getMonth()+1,0,12)),colors=['#f0f3eb','#dfead6','#c3d8ba','#8fb48b','#468360'];return `<div class="heatmap">${DAY.map(n=>`<div class="heat-head">${n[0]}</div>`).join('')}${Array.from({length:dayIndex(from)},()=>'<div class="heat-cell blank"></div>').join('')}${range(from,to).map(date=>{const s=habitDay(date),p=pct(s.done,s.total),color=s.total?colors[p===100?4:p>=66?3:p>=33?2:p>0?1:0]:'#f5f7f1';return `<button class="heat-cell ${date>today()?'future':''}" style="background:${color};${p>=66?'color:#fff':''}" data-action="heat-date" data-date="${date}" title="${fmtDate(date)}: ${s.done}/${s.total}" aria-label="${fmtDate(date)}, ${s.done} de ${s.total} hábitos"><b>${dateObj(date).getDate()}</b><span>${s.total?s.done+'/'+s.total:'—'}</span></button>`;}).join('')}</div><div class="heat-legend">Menos ${colors.map(c=>`<i style="background:${c}"></i>`).join('')} Más</div>`;}

function renderSettings(){return `${heading('Un espacio que sí es tuyo.','Personaliza tu nombre y conserva una copia de tu camino.')}<div class="settings-grid"><section class="panel settings-card"><h2>¿Cómo te llamas?</h2><p>Lo usaremos para saludarte. No se envía a ningún servidor.</p><form id="profile-form"><label class="field"><span>Tu nombre o apodo</span><input name="name" maxlength="60" value="${esc(state.profile.name)}" placeholder="Como te guste que te llamen"></label><button class="btn" type="submit">Guardar</button></form></section><section class="panel settings-card"><h2>Una copia que puedas llevarte</h2><p>Los datos se guardan en este navegador, no en GitHub ni en una cuenta. Exporta una copia para pasar tus avances al otro dispositivo o protegerlos si cambias de navegador.</p><div class="buttons"><button class="btn" data-action="export">${icon('download',16)}Exportar mis datos</button><button class="btn secondary" data-action="import">${icon('upload',16)}Importar copia</button></div><p class="muted-note">${state.lastExportAt?'Última exportación: '+esc(new Date(state.lastExportAt).toLocaleString('es')):'Aún no has exportado una copia.'}</p></section><section class="panel settings-card"><h2>Copias locales automáticas</h2><p>Guardamos hasta siete copias diarias anteriores en este navegador. No sustituyen una copia descargada: si borras los datos del navegador, también se borran estas copias.</p><button class="btn secondary" data-action="backups">${icon('back',16)}Ver copias disponibles</button></section><section class="panel settings-card"><h2>Pensado para muchos años</h2><ul><li>Calendario completo de ${FIRST} a ${LAST}, incluidos los años bisiestos.</li><li>Las marcas se guardan por fecha y hábito.</li><li>Las gráficas no incluyen el futuro ni los días no programados.</li><li>Archivar un hábito conserva sus registros.</li><li>Funciona sin internet una vez abierto el archivo.</li></ul><p class="muted-note">El calendario abarca 26 años; conservar los datos ese tiempo depende de tus copias y del almacenamiento de tus dispositivos.</p></section></div>`;}

function openModal(title,body){lastFocus=document.activeElement;const m=document.querySelector('#modal');m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="modal-close" aria-label="Cerrar">${icon('close',17)}</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();const field=m.querySelector('input:not([type=hidden]),textarea,select');if(field)field.focus();}
function closeModal(){document.querySelector('#modal').close();}
function confirmation(title,text,fn,label='Confirmar'){confirmAction=fn;openModal(title,`<p class="subtle confirmation-message">${esc(text)}</p><div class="modal-actions"><button class="btn secondary" data-action="modal-close">Cancelar</button><button class="btn" data-action="confirm">${esc(label)}</button></div>`);}
function daysPicker(selected){return `<div class="day-picker">${DAY.map((d,i)=>`<label><input type="checkbox" name="days" aria-label="${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][i]}" value="${i}" ${selected.includes(i)?'checked':''}><span>${d[0]}</span></label>`).join('')}</div>`;}
function field(name,label,value='',type='text',attrs=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function openEvent(eid,date=ui.date){const existing=eid?state.events.find(e=>e.id===eid):null,override=existing?state.overrides[`${eid}|${date}`]:null;const e=existing?{...existing,...override}:{id:'',title:'',start:'17:00',end:'17:45',category:'python',repeat:'once',days:[dayIndex(date)],startDate:date,endDate:'',notes:''};
 openModal(existing?'Editar bloque':'Un espacio para tu plan',`<form id="event-form"><input type="hidden" name="id" value="${esc(e.id)}"><input type="hidden" name="originalDate" value="${date}">${field('title','¿Qué vas a hacer?',e.title,'text','required maxlength="120" placeholder="Por ejemplo: practicar Python"')}
 ${existing?.repeat==='weekly'?`<label class="field"><span>Aplicar cambios a</span><select name="scope" id="event-scope"><option value="once">Solo este bloque del ${fmtDate(date)}</option><option value="series">Toda la serie semanal</option></select><small>Editar la serie también cambia sus fechas anteriores. Para conservarlas, modifica solo este bloque.</small></label>`:'<input name="scope" type="hidden" value="series">'}
 <div class="form-row">${field('date',existing?'Fecha del bloque':'Primera fecha',existing?.repeat==='weekly'?date:e.startDate,'date',`required min="${FIRST}-01-01" max="${LAST}-12-31"`)}<label class="field"><span>Área</span><select name="category">${Object.entries(CAT).map(([k,c])=>`<option value="${k}" ${k===e.category?'selected':''}>${c.name}</option>`).join('')}</select></label></div>
 <div class="form-row">${field('start','Empieza',e.start,'time','required')}${field('end','Termina',e.end,'time','required')}</div><div id="repeat-controls" ${existing?.repeat==='weekly'?'class="hide"':''}><label class="field"><span>Repetición</span><select name="repeat" id="event-repeat"><option value="once" ${e.repeat==='once'?'selected':''}>Solo una vez</option><option value="weekly" ${e.repeat==='weekly'?'selected':''}>Cada semana</option></select></label><div id="recurrence-wrap" class="${e.repeat==='weekly'?'':'hide'}"><div class="field"><span>Días de la semana</span>${daysPicker(e.days)}</div>${field('endDate','Repetir hasta (opcional)',e.endDate,'date',`min="${FIRST}-01-01" max="${LAST}-12-31"`)}</div></div>
 <label class="field"><span>Una nota para ti (opcional)</span><textarea name="notes" maxlength="1000" placeholder="Algo que quieras recordar…">${esc(e.notes)}</textarea></label><div id="event-conflict" class="notice hide"></div><div class="form-error" role="alert"></div><div class="modal-actions">${existing?`<button type="button" class="btn danger push" data-action="event-delete" data-id="${eid}" data-date="${date}">Quitar bloque</button>`:''}<button type="button" class="btn secondary" data-action="modal-close">Cancelar</button><button class="btn" type="submit">Guardar bloque</button></div></form>`);
}
function saveEvent(form){const fd=new FormData(form),eid=fd.get('id'),date=fd.get('date'),originalDate=fd.get('originalDate'),scope=fd.get('scope'),existing=state.events.find(e=>e.id===eid);const err=form.querySelector('.form-error');const title=String(fd.get('title')).trim(),start=String(fd.get('start')),end=String(fd.get('end')),category=fd.get('category'),notes=String(fd.get('notes')).trim(),repeat=fd.get('repeat'),days=fd.getAll('days').map(Number),endDate=String(fd.get('endDate')||'');
 if(!title){err.textContent='Ponle un nombre al bloque.';return;}if(!validDate(date)||!inRange(date)){err.textContent='Elige una fecha entre 2026 y 2051.';return;}if(minutes(end)<=minutes(start)){err.textContent='La hora de fin debe ser posterior al inicio. Divide un bloque nocturno en dos días.';return;}if(repeat==='weekly'&&scope==='series'&&!days.length){err.textContent='Elige al menos un día de la semana.';return;}if(endDate&&endDate<date&&scope==='series'){err.textContent='La fecha de fin debe ser igual o posterior a la primera fecha.';return;}
 const meta={title,start,end,category,notes};
 if(existing?.repeat==='weekly'&&scope==='once'){
  if(date===originalDate)state.overrides[`${eid}|${originalDate}`]=meta;
  else{state.overrides[`${eid}|${originalDate}`]={cancelled:true};state.events.push({...meta,id:id(),repeat:'once',days:[dayIndex(date)],startDate:date,endDate:''});}
 }else if(existing){Object.assign(existing,meta,{repeat,days:repeat==='weekly'?days:[dayIndex(date)],startDate:date,endDate:repeat==='weekly'?endDate:''});if(existing.repeat==='once'&&date!==originalDate&&state.eventLogs[originalDate]?.[eid]){state.eventLogs[date]??={};state.eventLogs[date][eid]=true;delete state.eventLogs[originalDate][eid];}}
 else state.events.push({...meta,id:id(),repeat,days:repeat==='weekly'?days:[dayIndex(date)],startDate:date,endDate:repeat==='weekly'?endDate:''});
 ui.date=date;closeModal();persist();toast('Bloque guardado. Tu horario se adapta a ti.');
}
function removeEvent(eid,date){const e=state.events.find(e=>e.id===eid);if(!e)return;openModal('Quitar del horario',`<p class="subtle">${esc(e.title)}</p><div class="modal-actions"><button class="btn secondary push" data-action="modal-close">Cancelar</button><button class="btn danger" data-action="event-remove-once" data-id="${eid}" data-date="${date}">Solo este bloque</button>${e.repeat==='weekly'?`<button class="btn danger" data-action="event-remove-future" data-id="${eid}" data-date="${date}">Este y los siguientes</button>`:''}</div><p class="muted-note">Los bloques anteriores a esta fecha no se eliminan.</p>`);}
function openHabit(hid){const h=state.habits.find(h=>h.id===hid),r=h?(habitRule(h,today())||h.rules[0]):null;openModal(h?'Editar hábito':'Un pequeño hábito nuevo',`<form id="habit-form"><input name="id" type="hidden" value="${hid||''}"><div class="form-row" style="grid-template-columns:90px 1fr">${field('emoji','Icono',h?.emoji||'🌱','text','maxlength="16" required')}${field('name','Nombre del hábito',h?.name||'','text','maxlength="90" required placeholder="Algo pequeño y posible"')}</div>${field('note','Una frase que te motive (opcional)',h?.note||'','text','maxlength="300" placeholder="¿Para qué quiero hacerlo?"')}<div class="field"><span>¿Qué días quieres hacerlo?</span>${daysPicker(r?.days||[0,1,2,3,4,5,6])}</div>${h?'<div class="notice">La nueva frecuencia se aplicará desde hoy. Los días anteriores y sus marcas se conservan.</div>':field('from','Empezar el',today(),'date',`required min="${FIRST}-01-01" max="${LAST}-12-31"`)}<div class="form-error" role="alert"></div><div class="modal-actions">${h?`<button class="btn danger push" type="button" data-action="habit-archive" data-id="${h.id}">Archivar</button>`:''}<button type="button" class="btn secondary" data-action="modal-close">Cancelar</button><button class="btn" type="submit">Guardar hábito</button></div></form>`);}
function saveHabit(form){const fd=new FormData(form),name=String(fd.get('name')).trim(),days=fd.getAll('days').map(Number),emoji=String(fd.get('emoji')).trim(),note=String(fd.get('note')).trim(),hid=fd.get('id'),h=state.habits.find(h=>h.id===hid),from=h?today():String(fd.get('from'));if(!name||!emoji||!days.length||!validDate(from)||!inRange(from)){form.querySelector('.form-error').textContent='Escribe un nombre, elige un icono, una fecha válida y al menos un día.';return;}if(h){Object.assign(h,{name,emoji,note});setRule(h,{from:today(),days,active:true});}else state.habits.push({id:id(),name,emoji,note,archived:false,rules:[{from,days,active:true}]});closeModal();persist();toast(h?'Hábito actualizado.':'Tu nuevo hábito ya tiene un lugar.');}
function openStep(rid,sid){const r=state.routes.find(r=>r.id===rid);if(!r)return;const s=r.steps.find(s=>s.id===sid);openModal(s?'Editar meta':'Mi siguiente meta',`<form id="step-form"><input type="hidden" name="route" value="${rid}"><input type="hidden" name="id" value="${sid||''}">${field('title','Nombre de la meta',s?.title||'','text','maxlength="120" required')}${field('period','Plazo orientativo',s?.period||'A mi ritmo','text','maxlength="100"')}${assessmentSelect(r,s)}<label class="field"><span>Lo que quiero aprender</span><textarea name="topics" maxlength="2000" required>${esc(s?.topics||'')}</textarea></label><label class="field"><span>¿Cómo demostraré mi progreso?</span><textarea name="goal" maxlength="2000" required>${esc(s?.goal||'')}</textarea></label><div class="form-error" role="alert"></div><div class="modal-actions">${s?`<button type="button" class="btn danger push" data-action="step-delete" data-route="${rid}" data-id="${sid}">Eliminar meta</button>`:''}<button type="button" class="btn secondary" data-action="modal-close">Cancelar</button><button class="btn" type="submit">Guardar meta</button></div></form>`);}
function saveStep(form){const fd=new FormData(form),r=state.routes.find(r=>r.id===fd.get('route'));if(!r)return;const s=r.steps.find(s=>s.id===fd.get('id')),fields=Object.fromEntries(['title','period','topics','goal','assessmentKey'].map(k=>[k,String(fd.get(k)||'').trim()]));if(!fields.title||!fields.topics||!fields.goal){form.querySelector('.form-error').textContent='Completa la meta, lo que aprenderás y la prueba de progreso.';return;}if(!EXAM_BANK[fields.assessmentKey]||(EXAM_BANK[fields.assessmentKey].route!=='any'&&EXAM_BANK[fields.assessmentKey].route!==r.id)){form.querySelector('.form-error').textContent='Elige una evaluación válida.';return;}if(s)Object.assign(s,fields);else r.steps.push({id:id(),...fields,done:false,completedAt:null});closeModal();persist();toast('Meta guardada.');}
function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportData(){if(recoveryData){downloadJSON(recoveryData,`rumbo-recuperacion-${today()}.json`);toast('Copia original preparada para recuperación.');return;}state.lastExportAt=new Date().toISOString();downloadJSON(state,`rumbo-copia-${today()}.json`);persist();toast('Copia preparada. Guárdala en un lugar que recuerdes.');}
async function importFile(file){if(!file)return;if(file.size>20*1024*1024){toast('La copia supera 20 MB. Comprueba que sea un archivo JSON de Rumbo.');return;}try{pendingImport=validate(JSON.parse(await file.text()));confirmation('¿Restaurar esta copia?',`Contiene ${pendingImport.events.length} bloques, ${pendingImport.habits.length} hábitos y ${Object.keys(pendingImport.habitLogs).length} días de registros. Reemplazará los datos de este navegador. Exporta los actuales antes si quieres conservarlos.`,()=>{state=pendingImport;pendingImport=null;if(recoveryData&&db){recoveryData=null;storageMode='indexeddb';storageError='';}ui.route=state.routes[0]?.id||'python';persist();toast('Copia restaurada. Tu camino sigue aquí.');},'Restaurar copia');}catch(err){toast(err.message||'No se pudo abrir la copia.');}}
async function showBackups(){if(storageMode!=='indexeddb'){openModal('Copias locales',`<p class="subtle">Este navegador usa el modo de almacenamiento alternativo. Puedes conservar tus datos exportando un archivo JSON.</p><div class="modal-actions"><button class="btn" data-action="export">Exportar mis datos</button></div>`);return;}const tx=db.transaction('backups'),keys=await request(tx.objectStore('backups').getAllKeys());openModal('Tus copias locales',`<p class="subtle">La copia de cada fecha contiene el estado anterior al primer cambio de ese día.</p>${keys.sort().reverse().map(d=>`<div class="archived-item"><span>${fmtDate(d,true)}</span><button class="btn soft small" data-action="restore-backup" data-date="${d}">Restaurar</button></div>`).join('')||'<div class="empty">Todavía no hay copias anteriores. Se crearán al guardar cambios.</div>'}`);}
function moveDate(n,kind){let next;if(kind==='day')next=add(ui.date,n);else{const anchor=kind==='calendar'?ui.date:ui.periodAnchor,mode=kind==='calendar'?ui.scheduleMode:ui.periodMode,d=dateObj(anchor);next=mode==='week'?add(anchor,n*7):key(new Date(d.getFullYear(),d.getMonth()+n,1,12));}if(!inRange(next)){toast('El calendario abarca de 2026 a 2051.');return;}if(kind==='period')ui.periodAnchor=next;else ui.date=next;render();}
function eventConflict(){const f=document.querySelector('#event-form');if(!f)return;const fd=new FormData(f),d=fd.get('date'),start=fd.get('start'),end=fd.get('end');if(!validDate(d)||!start||!end)return;const matches=eventsFor(d).filter(e=>e.id!==fd.get('id')&&minutes(start)<minutes(e.end)&&minutes(end)>minutes(e.start));const box=f.querySelector('#event-conflict');box.classList.toggle('hide',!matches.length);box.textContent=matches.length?`Este horario coincide con «${matches[0].title}». Puedes guardarlo así o ajustar las horas.`:'';}

document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id:eid,date,view,mode,delta,route}=el.dataset;
 try{switch(action){
 case 'view':learnUI.screen='levels';if(document.querySelector('#modal').open)closeModal();ui.view=view;render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'modal-close':closeModal();break;
 case 'confirm':{const fn=confirmAction;confirmAction=null;closeModal();await fn?.();break;}
 case 'date-step':moveDate(Number(delta),'day');break;
 case 'pick-date':if(inRange(date)){ui.date=date;render();}else toast('El calendario empieza en 2026 y llega hasta 2051.');break;
 case 'heat-date':ui.date=date;ui.view='today';render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'calendar-step':moveDate(Number(delta),'calendar');break;
 case 'go-today':ui.date=today();render();break;
 case 'schedule-mode':ui.scheduleMode=mode;render();break;
 case 'period-mode':ui.periodMode=mode;render();break;
 case 'period-step':moveDate(Number(delta),'period');break;
 case 'period-today':ui.periodAnchor=today();render();break;
 case 'metric':ui.metric=el.dataset.metric;render();break;
 case 'event-new':openEvent(null,date||ui.date);break;
 case 'event-edit':openEvent(eid,date);break;
 case 'event-toggle':eventToggle(eid,date);break;
 case 'event-delete':removeEvent(eid,date);break;
 case 'event-remove-once':state.overrides[`${eid}|${date}`]={cancelled:true};closeModal();persist();toast('Bloque retirado de esta fecha.');break;
 case 'event-remove-future':{const e=state.events.find(e=>e.id===eid);if(e)e.endDate=add(date,-1);for(const k of Object.keys(state.overrides))if(k.startsWith(eid+'|')&&k.split('|')[1]>=date)delete state.overrides[k];closeModal();persist();toast('Los bloques anteriores se conservaron.');break;}
 case 'habit-toggle':habitToggle(eid,date);break;
 case 'habit-new':openHabit(null);break;
 case 'habit-edit':openHabit(eid);break;
 case 'habit-archive':confirmation('¿Pausar este hábito?','Dejará de estar previsto desde hoy. Sus marcas de días anteriores se conservarán y podrás retomarlo cuando quieras.',()=>{const h=state.habits.find(h=>h.id===eid);if(!h)return;const rule=habitRule(h,today())||h.rules[0];h.rules=h.rules.filter(r=>r.from<=today());setRule(h,{from:today(),days:rule.days,active:false});h.archived=true;persist();toast('Hábito archivado. Tu historial se conserva.');},'Archivar');break;
 case 'habit-restore':{const h=state.habits.find(h=>h.id===eid);if(!h)return;const rule=habitRule(h,today())||h.rules[0];h.archived=false;setRule(h,{from:today(),days:rule.days,active:true});persist();toast('Hábito retomado desde hoy.');break;}
 case 'route':learnUI.screen='levels';ui.route=eid;render();break;
 case 'step-toggle':{toast('Completa el examen y la prueba práctica con más de 60% para aprobar este nivel.');break;}

 case 'step-new':openStep(route,null);break;
 case 'step-edit':openStep(route,eid);break;
 case 'step-delete':confirmation('¿Eliminar esta meta?','Se quitará esta meta de la ruta. Las demás metas y tus hábitos se conservarán.',()=>{const r=state.routes.find(r=>r.id===route);if(r)r.steps=r.steps.filter(s=>s.id!==eid);persist();},'Eliminar meta');break;
 case 'export':exportData();break;
 case 'import':document.querySelector('#import-file').click();break;
 case 'backups':await showBackups();break;
 case 'restore-backup':{const backup=await request(db.transaction('backups').objectStore('backups').get(date));const checked=validate(backup);confirmation('¿Volver a esta copia?',`Restaurarás el estado del ${fmtDate(date,true)}. Exporta los datos actuales antes si quieres conservarlos.`,()=>{state=checked;persist();toast('Copia local restaurada.');},'Restaurar');break;}
 }}catch(err){console.error(err);toast('No se pudo completar ese cambio. Tus datos no se han borrado.');}
});
document.addEventListener('change',ev=>{const el=ev.target;
 if(el.id==='selected-date'&&inRange(el.value)){ui.date=el.value;render();}
 if(el.id==='jump-year'||el.id==='jump-month'){const y=Number(document.querySelector('#jump-year').value),m=Number(document.querySelector('#jump-month').value);ui.date=key(new Date(y,m,1,12));render();}
 if(el.id==='event-repeat')document.querySelector('#recurrence-wrap').classList.toggle('hide',el.value!=='weekly');
 if(el.id==='event-scope'){document.querySelector('#repeat-controls').classList.toggle('hide',el.value==='once');const form=el.closest('form'),old=state.events.find(e=>e.id===new FormData(form).get('id'));if(old)form.elements.date.value=el.value==='series'?old.startDate:new FormData(form).get('originalDate');}
 if(el.id==='import-file'){importFile(el.files[0]);el.value='';}
 if(el.closest('#event-form'))eventConflict();
});
document.addEventListener('input',ev=>{if(ev.target.closest('#event-form'))eventConflict();});
document.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target;const formId=f.getAttribute('id');if(formId==='event-form')saveEvent(f);if(formId==='habit-form')saveHabit(f);if(formId==='step-form')saveStep(f);if(formId==='note-form'){state.notes[ui.date]=String(new FormData(f).get('note')).trim();persist();toast('Nota del día guardada.');}if(formId==='profile-form'){state.profile.name=String(new FormData(f).get('name')).trim();persist();toast('Listo. Tu espacio se siente un poco más tuyo.');}});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[role="button"][data-action]')){ev.preventDefault();ev.target.click();}});
document.querySelector('#modal').addEventListener('click',ev=>{if(ev.target===ev.currentTarget){const r=ev.currentTarget.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});
document.querySelector('#modal').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
window.addEventListener('beforeunload',ev=>{if(saving||storageError){ev.preventDefault();ev.returnValue='';}});
window.addEventListener('focus',()=>{updateSaveStatus();});
// Startup is at the end of extras.js, after all version-2 components are defined.
// Hosted version: installable shortcut and a local offline cache. No personal
// records are sent to the server; IndexedDB is separate from this asset cache.
if(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'){
 const manifest=document.createElement('link');manifest.rel='manifest';manifest.href='./manifest.webmanifest';document.head.append(manifest);
 if('serviceWorker' in navigator){let wasControlled=!!navigator.serviceWorker.controller;navigator.serviceWorker.register('./sw.js').then(r=>r.update().catch(()=>{})).catch(()=>{});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(wasControlled&&document.querySelector('.content'))toast('Hay una nueva versión de Rumbo disponible.',()=>location.reload(),'Actualizar');wasControlled=true;});}
}
